BEGIN;
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name_ar text NOT NULL,name_en text NOT NULL,description_ar text NOT NULL DEFAULT '',description_en text NOT NULL DEFAULT '',image_url text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),size text NOT NULL,price_cents bigint NOT NULL CHECK(price_cents>=0),unit_cost_cents bigint CHECK(unit_cost_cents>=0),on_hand integer NOT NULL DEFAULT 0 CHECK(on_hand>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand),UNIQUE(product_id,size));
CREATE TABLE IF NOT EXISTS shipping_zones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),emirate text NOT NULL,area text NOT NULL,customer_fee_cents bigint CHECK(customer_fee_cents>=0),carrier_cost_cents bigint CHECK(carrier_cost_cents>=0),active boolean NOT NULL DEFAULT true,UNIQUE(emirate,area));
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_key uuid UNIQUE NOT NULL,tracking_hash text UNIQUE NOT NULL,customer jsonb NOT NULL,zone_id uuid NOT NULL REFERENCES shipping_zones(id),shipping_fee_cents bigint NOT NULL CHECK(shipping_fee_cents>=0),carrier_cost_cents bigint,items_total_cents bigint NOT NULL DEFAULT 0 CHECK(items_total_cents>=0),status text NOT NULL DEFAULT 'awaiting_link' CHECK(status IN('awaiting_link','awaiting_payment','paid','preparing','out_for_delivery','completed','cancelled','expired')),payment_link text,payment_sent_at timestamptz,payment_expires_at timestamptz,payment_reference text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),variant_id uuid NOT NULL REFERENCES variants(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_cents bigint NOT NULL CHECK(unit_price_cents>=0),unit_cost_cents bigint CHECK(unit_cost_cents>=0));
CREATE TABLE IF NOT EXISTS finance_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('sale','operating_expense','funding_principal','principal_repayment','funding_return','inventory_purchase')),amount_cents bigint NOT NULL CHECK(amount_cents>0),note text NOT NULL DEFAULT '',order_id uuid REFERENCES orders(id),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS finance_sale_order ON finance_entries(order_id) WHERE kind='sale';
CREATE TABLE IF NOT EXISTS funding_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),amount_cents bigint NOT NULL CHECK(amount_cents>0),note text NOT NULL DEFAULT '',created_by text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_design(id integer PRIMARY KEY CHECK(id=1),settings jsonb NOT NULL,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor text NOT NULL,action text NOT NULL,entity_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_buckets(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
-- No seeded products, financial history, customers, staff identities or assumed zone prices.
COMMIT;
